#!/usr/bin/env python3
"""Builder for the full baseball dictionary INDEX.

Every term name from baseball-almanac's A-Z dictionary index, with the URL of its
definition page. This is the complete vocabulary — definitions for the curated
daily-rotation pool live in data/terms.json.

Coverage note: the letter pages for B and S truncated mid-list on fetch. Re-fetching
their tails returned hallucinated generic English words (bureau, subsidize, ...)
rather than page content, so those were discarded rather than stored. B is complete
through "breezer" and S through "stonewall"; both are flagged partial below.
"""
import json, os, urllib.parse

HERE = os.path.dirname(os.path.abspath(__file__))
DATA = os.path.join(HERE, "data")
TERM_URL = "https://www.baseball-almanac.com/dictionary-term.php?term="
INDEX_URL = "https://www.baseball-almanac.com/dictionary.php?alpha="

# Letters whose index page truncated during fetch, with the last term captured.
PARTIAL = {"b": "breezer", "s": "stonewall"}

RAW = os.path.join(DATA, "_index_raw")

LETTERS = {}


def load_raw_parts():
    """Parse data/_index_raw/*.txt — blocks of '## <letter>' then a comma list."""
    if not os.path.isdir(RAW):
        return
    for fn in sorted(os.listdir(RAW)):
        if not fn.endswith(".txt"):
            continue
        letter, buf = None, []
        with open(os.path.join(RAW, fn), encoding="utf-8") as f:
            for line in f:
                if line.startswith("## "):
                    if letter:
                        LETTERS[letter] = " ".join(buf)
                    letter, buf = line[3:].strip(), []
                elif line.strip():
                    buf.append(line.strip())
        if letter:
            LETTERS[letter] = " ".join(buf)


